// Kota artik kullanici bazli (19 Eyl 2026). Uygulamadan gelen istekler n8n'e tek bir
// sunucu IP'siyle ulastigi icin butun kullanicilar ayni kovayi paylasiyordu. IP zaten
// guvenilir bir ayrac degil: mobil veride degisir, ortak wifi'de birlesir. Backend
// gercek kimligi govdede 'kkbKimlik' olarak yolluyor. WordPress'ten gelen giris
// yapmamis isteklerde bu alan olmaz, eskisi gibi IP'ye duseriz.
const kimlikGovde = $input.first().json.body || $input.first().json;
const ip = kimlikGovde.kkbKimlik || $input.first().json.headers?.['x-forwarded-for']?.split(',')[0]?.trim() || $input.first().json.headers?.['x-real-ip'] || 'unknown';
const today = new Date().toISOString().slice(0, 10);
const key = 'rl_takvim_' + ip + '_' + today;
const staticData = $getWorkflowStaticData('global');
if (!staticData.rateLimits) staticData.rateLimits = {};
// 7 gunden eski sayaclari sil (15 Eyl 2026). Anahtarlar gun gun birikiyordu
// ('rl_<arac>_<ip>_<tarih>') ve hicbiri silinmedigi icin static data akisla
// birlikte kalici olarak buyuyor, zamanla akisi yavaslatiyordu.
const silSiniri = new Date(Date.now() - 7 * 86400000).toISOString().slice(0, 10);
for (const k of Object.keys(staticData.rateLimits)) {
  const kTarih = k.slice(-10);
  if (/^\d{4}-\d{2}-\d{2}$/.test(kTarih) && kTarih < silSiniri) delete staticData.rateLimits[k];
}
const current = staticData.rateLimits[key] || 0;
if (current >= 50) {
  return [{ json: { rateLimitExceeded: true } }];
}
staticData.rateLimits[key] = current + 1;
const body = $input.first().json.body || $input.first().json;
return [{ json: { rateLimitExceeded: false, prompt: body.prompt, dayCount: body.dayCount } }];

// job_id üretir. NOT: Bu workflow'un staticData'sı Worker workflow'unun
// staticData'sından AYRI (n8n'de her workflow'un kendi static data'sı var)
// — bu yüzden burada job kaydı YAZMIYORUZ, sadece kimliği üretip Worker'a
// iletiyoruz. İlk 'pending' kaydını Worker, kendi ilk adımında yazacak.
const jobId = [...Array(24)].map(() => Math.floor(Math.random()*36).toString(36)).join('');
const data = $input.first().json;
return [{ json: { ...data, jobId } }];
